package com.triathlon.prep.core;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
/** External synthetic fixtures; print payloads, no production device or persistent records. */
public final class ReceiptLayoutSelfCheck {
 static int passed,failed;interface Test{void run()throws Exception;}
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 static void test(String name,Test test){try{test.run();System.out.println("PASS "+(++passed)+" "+name);}catch(Throwable e){failed++;System.out.println("FAIL "+name+": "+e);}}
 static int width(String s,CheckInReceipt.Layout l){int width=0;for(int p=0;p<s.length();){int c=s.codePointAt(p);p+=Character.charCount(c);width+=c<128?l.latinGlyphDots:l.wideGlyphDots;}return width;}
 static String value(String s,int column,CheckInReceipt.Layout l){int used=0,p=0;while(p<s.length()&&used<column){int c=s.codePointAt(p);p+=Character.charCount(c);used+=c<128?l.latinGlyphDots:l.wideGlyphDots;}check(used==column,"value did not start at unified column");return s.substring(p);}
 static List<List<String>> fields(List<String> lines){int separators=0;List<List<String>> blocks=new ArrayList<>();List<String> block=new ArrayList<>();for(String line:lines){if(line.matches("-+")){separators++;if(separators==2){if(!block.isEmpty())blocks.add(block);break;}continue;}if(separators==1){if(line.isEmpty()){if(!block.isEmpty()){blocks.add(block);block=new ArrayList<>();}}else block.add(line);}}return blocks;}
 static ReceiptSelfCheck.Fixture fixture(RaceRoster.SwimTest swim){ReceiptSelfCheck.Fixture f=new ReceiptSelfCheck.Fixture(Verification.Mode.TEST,swim);f.pass();return f;}
 static CheckInReceipt.Document doc(ReceiptSelfCheck.Fixture f){return CheckInReceipt.preparePreview(f.flow,f.id);}
 static final CheckInReceipt.Layout NORMAL=new CheckInReceipt.Layout(384,12,24);
 static List<String> render(ReceiptSelfCheck.Fixture f){return CheckInReceipt.render(f.flow,doc(f),NORMAL);}
 public static void main(String[] args)throws Exception{
  test("paper omits all template notes and keeps the single TEST mark at bottom",()->{ReceiptSelfCheck.Fixture f=fixture(RaceRoster.SwimTest.UNKNOWN);List<String> lines=render(f);String text=String.join("\n",lines);for(CheckInReceipt.Step s:doc(f).steps)check(!text.contains(s.note),"paper still includes explanatory note "+s.note);check(!text.contains("（")&&!text.contains("）"),"template parentheses retained");check(lines.get(lines.size()-1).trim().equals("模拟样张 · 非有效凭条"),"single unified bottom TEST watermark absent");check(text.indexOf("模拟样张")==text.lastIndexOf("模拟样张"),"duplicate TEST paper marks");});
  test("two headings are logically centered and four fields share a value column",()->{ReceiptSelfCheck.Fixture f=fixture(RaceRoster.SwimTest.MARKED);List<String> lines=render(f);check(lines.get(0).equals("            合成赛事")&&lines.get(1).equals("           报到流程单"),"headings not centered at configured glyph width");List<List<String>> blocks=fields(lines);check(blocks.size()==4,"four field blocks absent");String[] labels={"姓名：","所属团体：","参赛组别：","比赛号码："};String[] values={"合成选手甲","合成团体","合成组","001"};for(int i=0;i<4;i++){check(blocks.get(i).get(0).startsWith(labels[i]),"field label/order changed");StringBuilder joined=new StringBuilder();for(String line:blocks.get(i))joined.append(value(line,132,NORMAL));check(joined.toString().equals(values[i]),"value lost or field column inconsistent");}});
  test("five numbered equal-format rows have a common right box column and unchanged swim inverse",()->{for(RaceRoster.SwimTest state:RaceRoster.SwimTest.values()){ReceiptSelfCheck.Fixture f=fixture(state);List<String> lines=render(f);int found=0;for(String line:lines)if(line.matches("[1-5]\\. .*")){int i=found++;check(line.startsWith((i+1)+". "+doc(f).steps.get(i).label),"step sequence differs");String box=doc(f).steps.get(i).checked?"[√]":"[　]";check(line.endsWith(box)&&width(line,NORMAL)==384&&width(line.substring(0,line.length()-box.length()),NORMAL)==336,"box not at common right column");}check(found==5,"five single rows absent");CheckInReceipt.Step swim=doc(f).steps.get(2);check(swim.checked==(state==RaceRoster.SwimTest.EXPLICIT_BLANK)&&swim.meaning==(state==RaceRoster.SwimTest.MARKED?CheckInReceipt.Meaning.NOT_REQUIRED:state==RaceRoster.SwimTest.EXPLICIT_BLANK?CheckInReceipt.Meaning.REQUIRED:CheckInReceipt.Meaning.CONFIRM),"swim meaning changed");}});
  test("long mixed fields retain legal data parentheses and wrap within value column at narrow widths",()->{
   String name="合成姓名(合法)ABCDEF",team="铁人(A组)Triathlon Club Long Long Long Mixed 中英文团体",group="男子(公开)Open 30-44 长组别",bib="000123456789012345678901234567890";
   ReceiptSelfCheck.Reader reader=new ReceiptSelfCheck.Reader(Verification.Mode.TEST);ReceiptSelfCheck.Algo algorithm=new ReceiptSelfCheck.Algo(Verification.Mode.TEST);RaceRoster roster=new RaceRoster("合成赛事(2026)",UUID.randomUUID().toString(),Arrays.asList(new RaceRoster.Entry(ReceiptSelfCheck.A,bib,name,group,team,RaceRoster.SwimTest.UNKNOWN)));
   Verification flow=new Verification(Verification.Mode.TEST,reader,algorithm,new ReceiptSelfCheck.Store(),new ReceiptSelfCheck.Time(),100,()->roster);String id=flow.begin();reader.read.ok(new Verification.Card("合成",ReceiptSelfCheck.A,new byte[]{1}));reader.capture.ok(new Verification.Capture(new byte[]{2},1,true));algorithm.reply.ok(new Verification.Comparison(Verification.Liveness.PASSED,90d,80d,Verification.ScoreRule.AT_LEAST,"SYNTHETIC_HOST"));CheckInReceipt.Document d=CheckInReceipt.preparePreview(flow,id);
   int[] dots={64,128,384},latin={8,8,12},wide={16,16,24},column={48,88,132};String[] want={name,team,group,bib};for(int k=0;k<dots.length;k++){CheckInReceipt.Layout layout=new CheckInReceipt.Layout(dots[k],latin[k],wide[k]);List<String> lines=CheckInReceipt.render(flow,d,layout);for(String line:lines)check(width(line,layout)<=dots[k],"payload line exceeds configured width");List<List<String>> blocks=fields(lines);check(blocks.size()==4,"narrow field blocks not readable");for(int i=0;i<4;i++){StringBuilder joined=new StringBuilder();for(String line:blocks.get(i))joined.append(value(line,column[k],layout));check(joined.toString().equals(want[i]),"mixed field dropped or continued outside value column");}String text=String.join("",lines).replace(" ","");check(text.contains("合成赛事(2026)"),"user heading parentheses removed");}
  });
  test("LIVE has no TEST mark and no notes while current eligibility remains session bound",()->{ReceiptSelfCheck.Fixture f=new ReceiptSelfCheck.Fixture(Verification.Mode.LIVE,RaceRoster.SwimTest.UNKNOWN);f.pass();CheckInReceipt.Document d=CheckInReceipt.prepare(f.flow,f.id);String text=String.join("\n",CheckInReceipt.render(f.flow,d,NORMAL));check(!text.contains("模拟")&&!text.contains("待确认"),"LIVE paper has TEST/unknown notes");check(d.steps.get(2).meaning==CheckInReceipt.Meaning.CONFIRM&&d.steps.get(2).note.equals("待确认"),"paper-external confirmation semantics lost");f.flow.next();try{CheckInReceipt.render(f.flow,d,NORMAL);throw new AssertionError("stale document printable");}catch(IllegalStateException expected){}});
  if(args.length>0){Path out=Paths.get(args[0]);Files.createDirectories(out);for(RaceRoster.SwimTest swim:RaceRoster.SwimTest.values())Files.write(out.resolve("receipt-"+swim+".txt"),render(fixture(swim)),StandardCharsets.UTF_8);}
  System.out.println("RESULT passed="+passed+" failed="+failed);if(failed!=0)throw new AssertionError("PREP30 target checks failed="+failed);
 }
}
